export function isValidIsbn10(value) {
    const s = value.replace(/-/g, '');
    if (!/^[0-9]{9}[0-9X]$/.test(s))
        return false;
    let sum = 0;
    for (let i = 0; i < 10; i++)
        sum += (10 - i) * (s[i] === 'X' ? 10 : Number(s[i]));
    return sum % 11 === 0;
}
